 {
  "turns": [
    {
      "speaker": "customer",
      "text": "my internet is down again!! this is ridiculous 😡",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "Hello, welcome to Nimbus Telecom. I am Sana. How can I help you today?",
      "tags": ["greeting"]
    },
    {
      "speaker": "customer",
      "text": "i just told u my net is out. i need it for work and im so annoyed",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "Please provide your account number and full name for verification.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Karan Das, account 88248519",
      "tags": ["identity_verification"]
    },
    {
      "speaker": "agent",
      "text": "Thank you. What is the phone number associated with the account?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "It is 97737 01293",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I see a network outage in your area. I promise this will never happen again.",
      "tags": ["prohibited_promise"]
    },
    {
      "speaker": "customer",
      "text": "well i hope so because this is the third time this month",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I will raise a network ticket to prioritize the repair for your street.",
      "tags": ["action:technician_or_ticket"]
    },
    {
      "speaker": "customer",
      "text": "oh okay, thanks. that sounds good",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "The ticket is now open. Is there anything else I can assist you with? I have raised the ticket and the team will update you. Goodbye.",
      "tags": ["closure"]
    },
    {
      "speaker": "customer",
      "text": "no that's all, thanks Sana! 😊",
      "tags": []
    }
  ]
}
